  void ShowPreview(){ClearUi(right);project.Preview=project.Preview??new PreviewOptions();preview.Project=project;var layout=new TableLayoutPanel{Dock=DockStyle.Fill,RowCount=3,ColumnCount=1,BackColor=Theme.Card};layout.RowStyles.Add(new RowStyle(SizeType.Absolute,250));layout.RowStyles.Add(new RowStyle(SizeType.Percent,100));layout.RowStyles.Add(new RowStyle(SizeType.Absolute,42));right.Controls.Add(layout);var controls=new FlowLayoutPanel{Dock=DockStyle.Fill,Padding=new Padding(10),AutoScroll=true,BackColor=Theme.Card};layout.Controls.Add(controls,0,0);
   controls.Controls.Add(Theme.Button("Полигон Forts · точная физика",ShowRange,true));controls.Controls.Add(Theme.Button("Вписать",()=>preview.Fit()));controls.Controls.Add(Theme.Button("↶",preview.Undo));controls.Controls.Add(Theme.Button("↷",preview.Redo));
