   var tool=Theme.Combo();tool.Width=120;tool.Items.AddRange(new[]{"Балка","Объект","Прицел","Стереть"});tool.SelectedItem=preview.Tool;tool.SelectedIndexChanged+=(s,e)=>{preview.Tool=Convert.ToString(tool.SelectedItem);preview.Invalidate();};controls.Controls.Add(tool);var team=Theme.Combo();team.Width=155;team.Items.AddRange(new[]{"Своя сторона","Вражеская цель"});team.SelectedIndex=project.Preview.BuildTeam==2?1:0;team.SelectedIndexChanged+=(s,e)=>{project.Preview.BuildTeam=team.SelectedIndex+1;Mark();};controls.Controls.Add(team);
   var weapon=selected!=null&&selected.Kind=="weapons"?selected:project.Entities.FirstOrDefault(x=>x.Kind=="weapons");if(weapon!=null){var ammo=Theme.Combo();ammo.Width=190;foreach(string key in weapon.Ammo){var pr=preview.Resolve(key,"projectiles");ammo.Items.Add(new Choice(key,pr==null?key:pr.NameRu));}ammo.SelectedItem=ammo.Items.Cast<Choice>().FirstOrDefault(x=>x.Key==project.Preview.Ammo);if(ammo.SelectedItem==null&&ammo.Items.Count>0)ammo.SelectedIndex=0;if(ammo.SelectedItem!=null)project.Preview.Ammo=((Choice)ammo.SelectedItem).Key;ammo.SelectedIndexChanged+=(s,e)=>{project.Preview.Ammo=((Choice)ammo.SelectedItem).Key;Mark();};controls.Controls.Add(ammo);controls.Controls.Add(Theme.Button("▶ Анимация",preview.Fire));controls.Controls.Add(Theme.Button("Ⅱ",preview.PauseAnimation));controls.Controls.Add(Theme.Button("Сброс",preview.Reset));}
   var speed=Theme.Combo();speed.Width=105;speed.Items.AddRange(new[]{"×0,1","×0,25","×0,5","×1"});double[] rates={.1,.25,.5,1};int chosen=Array.IndexOf(rates,project.Preview.TimeScale);speed.SelectedIndex=chosen<0?1:chosen;speed.SelectedIndexChanged+=(s,e)=>{project.Preview.TimeScale=rates[speed.SelectedIndex];Mark();};controls.Controls.Add(speed);controls.Controls.Add(Theme.Label("Угол°",8));var angle=new NumericUpDown{Minimum=-89,Maximum=89,DecimalPlaces=1,Width=65,Value=(decimal)Math.Max(-89,Math.Min(89,project.Preview.AimDegrees)),BackColor=Theme.Input,ForeColor=Theme.Text};bool aimSync=false;angle.ValueChanged+=(s,e)=>{if(aimSync)return;project.Preview.AimDegrees=(double)angle.Value;Mark();};preview.AimChanged=()=>{aimSync=true;angle.Value=(decimal)project.Preview.AimDegrees;aimSync=false;};controls.Controls.Add(angle);controls.Controls.Add(Theme.Label("Мощность%",8));var power=new NumericUpDown{Minimum=0,Maximum=100,Width=60,Value=(decimal)(Math.Max(0,Math.Min(1,project.Preview.Power))*100),BackColor=Theme.Input,ForeColor=Theme.Text};power.ValueChanged+=(s,e)=>{project.Preview.Power=(double)power.Value/100;Mark();};controls.Controls.Add(power);
   foreach(string option in new[]{"Сетка","Рамки","Траектория","Следить за снарядом"}){string name=option;var cb=new UiCheckBox{Text=name,AutoSize=true,ForeColor=Theme.Text,Margin=new Padding(4,8,3,3),Checked=name=="Сетка"?project.Preview.Grid:name=="Рамки"?project.Preview.Bounds:name=="Траектория"?project.Preview.Trajectory:project.Preview.FollowProjectile};cb.CheckedChanged+=(s,e)=>{if(name=="Сетка")project.Preview.Grid=cb.Checked;else if(name=="Рамки")project.Preview.Bounds=cb.Checked;else if(name=="Траектория")project.Preview.Trajectory=cb.Checked;else project.Preview.FollowProjectile=cb.Checked;Mark();};controls.Controls.Add(cb);}
