  void ShowRange(){using(var form=new UiForm{Text="Полигон Forts · игровой движок",ClientSize=new Size(770,730),MinimumSize=new Size(700,650),StartPosition=FormStartPosition.CenterParent,BackColor=Theme.Card,ForeColor=Theme.Text,Font=Font}){var f=Theme.Flow(true);form.Controls.Add(f);f.Controls.Add(Theme.Label("Физику считает сама Forts",22,true));f.Controls.Add(Theme.Label("Редактор готовит отдельную карту и служебный мод из текущего проекта. В игре работают настоящие балки, отдача, разрушения, звуки и сценарии.",11));Header(f,"Как открыть");f.Controls.Add(Theme.Label("1. Подготовьте полигон кнопкой ниже.\n2. Перезапустите Forts после сборки или обновления.\n3. Песочница → карты игрока → «Полигон FMS».\n4. Постройте или выберите свою пушку, прицельтесь и стреляйте обычным управлением игры. Для восстановления сцены перезапустите матч.",10));f.Controls.Add(Theme.Label("Сцена крепится к верхнему переднему узлу штатного форта, над землёй. Для каждой стороны нужна одна связная конструкция. Балки цели создавайте с выбранной стороной «Вражеская цель». Полигон строит макет поэтапно, ожидая готовности опор. На большой макет может потребоваться время. Параметры объектов сохраняются.",9));
    var ground=new UiCheckBox{Text="Фундамент под нижними узлами макета",AutoSize=true,ForeColor=Theme.Text,Checked=project.Preview.RangeGrounded};ground.CheckedChanged+=(s,e)=>{project.Preview.RangeGrounded=ground.Checked;Mark();};f.Controls.Add(ground);f.Controls.Add(Theme.Label("С фундаментом макет стоит на отдельной площадке. Без него он висит на одном узле и может опрокинуться: Forts считает настоящую устойчивость.",9));var result=Theme.TextBox(String.Join("\r\n",FortsRange.Issues(project).DefaultIfEmpty("Макет готов к переносу.")));result.Width=700;result.Height=95;result.Multiline=true;result.ReadOnly=true;result.ScrollBars=ScrollBars.Vertical;f.Controls.Add(result);string mapPath=Path.Combine(project.GameRoot,"data","maps",FortsRange.MapName(project));var line=new FlowLayoutPanel{Width=700,AutoSize=true};line.Controls.Add(Theme.Button("Подготовить полигон",()=>Safe(()=>{string temp=Path.Combine(Path.GetDirectoryName(autosavePath),"ranges",Guid.NewGuid().ToString("N"));mapPath=FortsRange.Prepare(project,temp,true);result.Text="Готово: "+mapPath+"\r\nПерезапустите Forts и выберите карту «Полигон FMS».";}),true));line.Controls.Add(Theme.Button("Открыть Forts",()=>Safe(()=>{if(Process.GetProcessesByName("Forts").Length>0){result.Text="Forts уже запущена. Сохраните матч и перезапустите игру после обновления полигона. Затем: Песочница → карты игрока → «Полигон FMS».";return;}Process.Start("steam://rungameid/410900");})));line.Controls.Add(Theme.Button("Папка карты",()=>Safe(()=>{if(!Directory.Exists(mapPath))throw new Exception("Сначала подготовьте полигон.");Process.Start(mapPath);})));f.Controls.Add(line);Header(f,"Журнал настоящих попаданий");var report=Theme.TextBox(FortsRange.Report(project));report.Width=700;report.Height=140;report.Multiline=true;report.ReadOnly=true;report.ScrollBars=ScrollBars.Both;report.WordWrap=false;report.Font=new Font("Consolas",9);f.Controls.Add(report);f.Controls.Add(Theme.Button("Обновить журнал",()=>report.Text=FortsRange.Report(project)));f.Controls.Add(Theme.Label("BUILDING — идёт сборка. READY — все элементы созданы. INCOMPLETE — макет собран не полностью. ERROR — причина отказа движка. SHOT — снаряд и фактическая скорость. HIT — материал и переданный игрой урон. CS_UNSTABLE — опора не готова; CS_NODESTOOFAR — превышена длина; CS_OBSTRUCTION — препятствие.",9));form.ShowDialog(this);}}
